import type { FeatureCollection } from 'geojson'
import type { Demo, Location, Metadata, RestStop, RouteRequest, RouteResponse } from '../types'
import data from './fallback.json'

// Generated by backend/scripts/export_fallback.py from the real API. The page opens on
// this so it never waits on, or breaks because of, a sleeping backend.
export const FALLBACK = data as unknown as {
  locations: Location[]
  buildings: (Omit<Location, 'osm_url'> & { osm_url: string | null; aliases?: string[]; source_url?: string })[]
  metadata: Metadata
  stops: RestStop[]
  features: FeatureCollection
  demos: Demo[]
  routes: { request: RouteRequest; response: RouteResponse }[]
}

export const SAVED_NOTE =
  'Saved demo result: campus data is still connecting, so this route was calculated ahead of time by the same router.'

function key({ origin, destination, preferences: p }: RouteRequest) {
  return JSON.stringify([
    origin.lat,
    origin.lon,
    destination.lat,
    destination.lon,
    p.noise,
    p.crowds,
    p.traffic,
    p.green,
    p.pace,
    p.max_detour,
  ])
}

/** A precomputed result for exactly this request, or null. */
export function savedRoute(request: RouteRequest): RouteResponse | null {
  const match = FALLBACK.routes.find((r) => key(r.request) === key(request))
  return match ? { ...match.response, notes: [SAVED_NOTE, ...match.response.notes] } : null
}
